import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const base = resolve('outputs/白鹭引擎重构工程知识库');
const dir = resolve(base, 'experiments/reliable-event-probe');
const model = readFileSync(resolve(dir, 'model.mjs'), 'utf8');
const run = readFileSync(resolve(dir, 'run.mjs'), 'utf8');
const hash = x => createHash('sha256').update(x).digest('hex');
const results = [];
for (const name of ['reliable-event-probe-red-results.json', 'reliable-event-probe-red-input-results.json', 'reliable-event-probe-results.json']) {
  const report = JSON.parse(readFileSync(resolve(base, 'evidence', name), 'utf8'));
  const matchingHashes = report.sourceHashes.every(x => hash(report.sourceSnapshots?.find(s => s.path === x.path)?.source ?? readFileSync(x.path, 'utf8')) === x.sha256);
  const correctCounts = report.counts.total === report.results.length && report.counts.passed === report.results.filter(x => x.status === 'passed').length && report.counts.failed === report.results.filter(x => x.status === 'failed').length;
  if (!matchingHashes || !correctCounts) throw new Error(name + ' report mismatch');
  if (report.sourceSnapshots) {
    const redDir = resolve('work/reliable-event-probe', name.replace('.json', ''));
    mkdirSync(redDir, { recursive: true });
    for (const item of report.sourceSnapshots) writeFileSync(resolve(redDir, item.path.endsWith('model.mjs') ? 'model.mjs' : 'run.mjs'), item.source);
    const replayPath = resolve(redDir, 'replay.json');
    const replay = spawnSync(process.execPath, [resolve(redDir, 'run.mjs'), '--output=' + replayPath], { encoding: 'utf8' });
    const observed = JSON.parse(readFileSync(replayPath, 'utf8'));
    if (replay.status !== 1 || JSON.stringify(observed.counts) !== JSON.stringify(report.counts) || observed.results.some((x,i) => x.status !== report.results[i].status)) throw new Error(name + ' replay mismatch');
  }
  results.push({ name: 'hashes, counts and preserved-source replay: ' + name, status: 'passed', observations: { matchingHashes, correctCounts, originalCounts: report.counts, replayed: !!report.sourceSnapshots } });
}
const mutations = [
  ['duplicate side effect', "if (event.sequence <= this.watermark) return { status: 'duplicate', ack: this.ack() };", "if (event.sequence <= this.watermark) { this.effects.push(event.effect); return { status: 'duplicate', ack: this.ack() }; }"],
  ['consume sequence gap', "if (event.sequence !== this.watermark + 1) return { status: 'gap', expected: this.watermark + 1 };", '// gap guard removed'],
  ['drop outbox on send', 'return structuredClone(this.outbox);', 'const copy = structuredClone(this.outbox); this.outbox = []; return copy;'],
  ['ignore queue capacity', 'if (this.outbox.length >= this.capacity) return null;', '// capacity guard removed'],
  ['clear event state on graphics recovery', 'restoreGraphics(epoch) { this.graphicsEpoch = epoch; }', 'restoreGraphics(epoch) { this.graphicsEpoch = epoch; this.outbox = []; this.watermark = 0; }'],
  ['accept wrong session ACK', 'if (!this.sameIdentity(ack) || !Number.isSafeInteger(ack.watermark)', 'if (!Number.isSafeInteger(ack.watermark)'],
];
for (let i = 0; i < mutations.length; i++) {
  const [name, oldText, newText] = mutations[i];
  if (!model.includes(oldText)) throw new Error('missing mutation target ' + name);
  const mutantDir = resolve('work/reliable-event-probe', 'mutation-' + i);
  mkdirSync(mutantDir, { recursive: true });
  writeFileSync(resolve(mutantDir, 'model.mjs'), model.replace(oldText, newText));
  writeFileSync(resolve(mutantDir, 'run.mjs'), run);
  const replayPath = resolve(mutantDir, 'replay.json');
  const execution = spawnSync(process.execPath, [resolve(mutantDir, 'run.mjs'), '--output=' + replayPath], { encoding: 'utf8' });
  const observed = JSON.parse(readFileSync(replayPath, 'utf8'));
  const killed = execution.status === 1 && observed.counts.failed > 0;
  results.push({ name: 'mutation: ' + name, status: killed ? 'passed' : 'failed', observations: { mutantSHA256: hash(model.replace(oldText, newText)), exitCode: execution.status, failedTests: observed.results.filter(x => x.status === 'failed').map(x => ({ name: x.name, error: x.error })) } });
}
const output = resolve(base, 'evidence/reliable-event-probe-verification-results.json');
const verificationPath = fileURLToPath(import.meta.url);
const verificationSource = readFileSync(verificationPath, 'utf8');
const report = { schemaVersion: 1, experiment: 'reliable-event-probe-verification', checkedAtUtc: new Date().toISOString(), environment: { runtime: process.version, executable: process.execPath, platform: process.platform, architecture: process.arch, scope: 'source replay and six targeted behavioral mutations' }, counts: { total: results.length, passed: results.filter(x => x.status === 'passed').length, failed: results.filter(x => x.status === 'failed').length }, results, sourceHashes: [...['model.mjs', 'run.mjs'].map(name => ({ path: resolve(dir, name), sha256: hash(readFileSync(resolve(dir, name), 'utf8')) })), { path: verificationPath, sha256: hash(verificationSource) }], sourceSnapshots: [{ path: verificationPath, sha256: hash(verificationSource), source: verificationSource }], limitations: ['Mutations target six known failure modes only; this is not exhaustive mutation coverage or independent audit.', 'Red source replay reproduces preserved in-memory models, not production engine or network execution.'] };
writeFileSync(output, JSON.stringify(report, null, 2) + '\n');
console.log(JSON.stringify({ output, counts: report.counts, results: results.map(x => ({ name: x.name, status: x.status, failures: x.observations.failedTests?.map(t => t.name) })) }, null, 2));
if (report.counts.failed) process.exitCode = 1;
